export interface RecentTrack {
  from: string;
  to: string;
  date: string;
  timestamp: number;
}

const STORAGE_KEY = 'trayago_recent_tracks';

export const recentTracksManager = {
  get: (): RecentTrack[] => {
    if (typeof window === 'undefined') return [];
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  },

  add: (track: RecentTrack) => {
    if (typeof window === 'undefined') return;
    try {
      let tracks = recentTracksManager.get();
      
      // Remove duplicate if exists (same route)
      tracks = tracks.filter(t => !(t.from === track.from && t.to === track.to));
      
      // Add to beginning
      tracks.unshift(track);
      
      // Limit to 3
      tracks = tracks.slice(0, 3);
      
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tracks));
    } catch (e) {
      console.error('Failed to save recent track', e);
    }
  }
};
